// =====================================================
// SUMAMRY REPO
// =====================================================

	public List<MASTER_Summary_Entity> getSummaryDataByDate(Date reportDate) {

		String sql = "SELECT * FROM BRRS_MASTER_SUMMARYTABLE WHERE REPORT_DATE = ?";

		return jdbcTemplate.query(sql, new Object[] { reportDate }, new MASTER_Summary_RowMapper());
	}

	// Fetch existing live summary record
	public MASTER_Summary_Entity findByReportDate(Date reportDate) {
		String selectSql = "SELECT * FROM BRRS_MASTER_SUMMARYTABLE WHERE TRUNC(REPORT_DATE) = TRUNC(?)";
		List<MASTER_Summary_Entity> list = jdbcTemplate.query(selectSql,
				new BeanPropertyRowMapper<>(MASTER_Summary_Entity.class), reportDate);
		return list.isEmpty() ? null : list.get(0);
	}

	// Fetch existing mod record if any pending modifications exist
	public MASTER_Summary_Entity findModRecordByReportDate(Date reportDate) {
		String selectSql = "SELECT * FROM BRRS_MASTER_MOD_SUMMARYTABLE WHERE TRUNC(REPORT_DATE) = TRUNC(?)";
		List<MASTER_Summary_Entity> list = jdbcTemplate.query(selectSql,
				new BeanPropertyRowMapper<>(MASTER_Summary_Entity.class), reportDate);
		return list.isEmpty() ? null : list.get(0);
	}

// =====================================================
// ARCHIVAL  SUMAMRY REPO
// =====================================================

	public List<Object[]> get_MASTER_archival() {

		String sql = "SELECT REPORT_DATE, REPORT_VERSION " + "FROM BRRS_MASTER_ARCHIVALTABLE_SUMMARY "
				+ "ORDER BY REPORT_VERSION";

		return jdbcTemplate.query(sql,
				(rs, rowNum) -> new Object[] { rs.getDate("REPORT_DATE"), rs.getBigDecimal("REPORT_VERSION") });
	}

	public List<MASTER_Archival_Summary_Entity> getDataByDateListArchival(Date reportDate, BigDecimal reportVersion) {

		String sql = "SELECT * FROM BRRS_MASTER_ARCHIVALTABLE_SUMMARY "
				+ "WHERE REPORT_DATE = ? AND REPORT_VERSION = ?";

		return jdbcTemplate.query(sql, new Object[] { reportDate, reportVersion },
				new MASTER_Archival_Summary_RowMapper());
	}

	public List<MASTER_Archival_Summary_Entity> getarchivaldatabydateListWithVersion() {

		String sql = "SELECT * FROM BRRS_MASTER_ARCHIVALTABLE_SUMMARY " + "WHERE REPORT_VERSION IS NOT NULL "
				+ "ORDER BY REPORT_DATE ASC";

		return jdbcTemplate.query(sql, new MASTER_Archival_Summary_RowMapper());
	}

	public BigDecimal findMaxVersion(Date reportDate) {

		String sql = "SELECT MAX(REPORT_VERSION) FROM BRRS_MASTER_ARCHIVALTABLE_SUMMARY WHERE REPORT_DATE = ?";

		return jdbcTemplate.queryForObject(sql, new Object[] { reportDate }, BigDecimal.class);
	}

