// ====================== UPDATE (MAKER) ======================

	@Transactional
	public void updateReport(MASTER_Summary_Entity updatedEntity) {
		System.out.println("Came to MASTER Update");
		System.out.println("Report Date: " + updatedEntity.getReport_date());

		// 1. Fetch live summary record as baseline reference
		MASTER_Summary_Entity liveSummary = findByReportDate(updatedEntity.getReport_date());
		if (liveSummary == null) {
			throw new RuntimeException(
					"Record not found in live summary table for REPORT_DATE : " + updatedEntity.getReport_date());
		}

		// 2. Use existing mod record, else copy from live baseline
		MASTER_Summary_Entity modRecord = findModRecordByReportDate(updatedEntity.getReport_date());
		if (modRecord == null) {
			modRecord = new MASTER_Summary_Entity();
			BeanUtils.copyProperties(liveSummary, modRecord);
		}

		// 3. Keep old copy for audit comparison
		MASTER_Summary_Entity oldcopy = new MASTER_Summary_Entity();
		BeanUtils.copyProperties(modRecord, oldcopy);

		try {
			// Apply updates ONLY to modRecord (live tables untouched)
			applyChangesToEntity(updatedEntity, modRecord);
		} catch (Exception e) {
			throw new RuntimeException("Error while updating MASTER fields", e);
		}

		// 4. Evaluate audit changes
		String changes = auditService.getChanges(oldcopy, modRecord);
		System.out.println("MASTER Changes Length = " + (changes != null ? changes.length() : 0));

		// 5. Maker-Checker flags
		modRecord.setEntity_flg("Y");
		modRecord.setModify_flg("Y");
		modRecord.setDel_flg("N");

		// 6. Save/Update into MOD table only
		saveModSummaryEntity(modRecord);
		System.out.println("✔ Record saved into BRRS_MASTER_MOD_SUMMARYTABLE for Checker Approval");

		// 7. Audit trail
		if (changes != null && !changes.isEmpty()) {
			auditService.compareEntitiesmanual(oldcopy, modRecord, updatedEntity.getReport_date().toString(),
					"MASTER Summary Screen", "BRRS_MASTER_MOD_SUMMARYTABLE");
		}
	}

// Copies non-null / non-blank values from the screen entity to the target entity
	private void applyChangesToEntity(MASTER_Summary_Entity updatedEntity, MASTER_Summary_Entity targetEntity) {
		for (FieldGroup group : MASTER_FIELD_GROUPS) {
			for (int i : group.rows) {
				for (String field : group.fields) {
					String suffix = "R" + i + "_" + field;
					String getterName = "get" + suffix;
					String setterName = "set" + suffix;

					try {
						Method getter = MASTER_Summary_Entity.class.getMethod(getterName);
						Object value = getter.invoke(updatedEntity);

						if (value == null) {
							continue;
						}
						// Blank text should not overwrite existing text
						if (value instanceof String && ((String) value).trim().isEmpty()) {
							continue;
						}

						Method setter = MASTER_Summary_Entity.class.getMethod(setterName, getter.getReturnType());
						setter.invoke(targetEntity, value);

					} catch (NoSuchMethodException e) {
						// Skip gracefully if method doesn't exist
					} catch (Exception e) {
						throw new RuntimeException("Error applying field: " + getterName, e);
					}
				}
			}
		}
	}

// ====================== SAVE TO MOD TABLE ======================

	public void saveModSummaryEntity(MASTER_Summary_Entity entity) {
		NamedParameterJdbcTemplate namedParamJdbc = new NamedParameterJdbcTemplate(jdbcTemplate);

		String checkSql = "SELECT COUNT(*) FROM BRRS_MASTER_MOD_SUMMARYTABLE WHERE TRUNC(REPORT_DATE) = TRUNC(:reportDate)";
		MapSqlParameterSource checkParams = new MapSqlParameterSource("reportDate", entity.getReport_date());
		Integer count = namedParamJdbc.queryForObject(checkSql, checkParams, Integer.class);

		MapSqlParameterSource params = new MapSqlParameterSource().addValue("reportDate", entity.getReport_date())
				.addValue("entity_flg", entity.getEntity_flg()).addValue("modify_flg", entity.getModify_flg())
				.addValue("del_flg", entity.getDel_flg());

		StringBuilder updateSetSql = new StringBuilder(
				"MODIFY_FLG = :modify_flg, ENTITY_FLG = :entity_flg, DEL_FLG = :del_flg");
		List<String> insertColumns = new ArrayList<>(
				Arrays.asList("REPORT_DATE", "ENTITY_FLG", "MODIFY_FLG", "DEL_FLG"));
		List<String> insertValues = new ArrayList<>(
				Arrays.asList(":reportDate", ":entity_flg", ":modify_flg", ":del_flg"));

		for (FieldGroup group : MASTER_FIELD_GROUPS) {
			for (int i : group.rows) {
				for (String field : group.fields) {
					String columnName = "R" + i + "_" + field.toUpperCase();
					String getterName = "getR" + i + "_" + field;
					String paramName = "r" + i + "_" + field;

					try {
						Method getter = MASTER_Summary_Entity.class.getMethod(getterName);
						Object value = getter.invoke(entity);

						params.addValue(paramName, value);

						updateSetSql.append(", ").append(columnName).append(" = :").append(paramName);
						insertColumns.add(columnName);
						insertValues.add(":" + paramName);

					} catch (NoSuchMethodException e) {
						// Skip
					} catch (Exception e) {
						throw new RuntimeException("Error mapping column for MOD table: " + columnName, e);
					}
				}
			}
		}

		if (count != null && count > 0) {
			String updateSql = "UPDATE BRRS_MASTER_MOD_SUMMARYTABLE SET " + updateSetSql
					+ " WHERE TRUNC(REPORT_DATE) = TRUNC(:reportDate)";
			namedParamJdbc.update(updateSql, params);
			System.out.println("✔ BRRS_MASTER_MOD_SUMMARYTABLE updated successfully.");
		} else {
			String insertSql = "INSERT INTO BRRS_MASTER_MOD_SUMMARYTABLE (" + String.join(", ", insertColumns)
					+ ") VALUES (" + String.join(", ", insertValues) + ")";
			namedParamJdbc.update(insertSql, params);
			System.out.println("✔ BRRS_MASTER_MOD_SUMMARYTABLE inserted successfully.");
		}
	}

// ====================== APPROVE (CHECKER) ======================

	@Transactional
	public void approveReport(Date reportDate) {
		// 1. Fetch pending modification record from MOD table
		MASTER_Summary_Entity modRecord = jdbcTemplate.queryForObject(
				"SELECT * FROM BRRS_MASTER_MOD_SUMMARYTABLE WHERE TRUNC(REPORT_DATE) = TRUNC(?) AND MODIFY_FLG = 'Y'",
				new BeanPropertyRowMapper<>(MASTER_Summary_Entity.class), reportDate);

		if (modRecord == null) {
			throw new RuntimeException("No pending modification found for approval on date: " + reportDate);
		}

		// 2. Transfer MOD values to live summary and detail tables (ONLY on approval)
		transferModValuesToLiveTables(modRecord, reportDate);

		// 3. Mark as approved in MOD table
		jdbcTemplate.update(
				"UPDATE BRRS_MASTER_MOD_SUMMARYTABLE SET MODIFY_FLG = 'N' WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
				reportDate);

		System.out.println(
				"✔ MASTER Checker Approved Successfully: MOD values successfully transferred to Summary & Detail live tables.");
	}

// Pushes all non-null MOD values to the live Summary & Detail tables (one UPDATE per table)
	private void transferModValuesToLiveTables(MASTER_Summary_Entity modRecord, Date reportDate) {
		StringBuilder setSql = new StringBuilder();
		List<Object> args = new ArrayList<>();

		for (FieldGroup group : MASTER_FIELD_GROUPS) {
			for (int i : group.rows) {
				for (String field : group.fields) {
					String columnName = "R" + i + "_" + field.toUpperCase();
					String getterName = "getR" + i + "_" + field;

					try {
						Method getter = MASTER_Summary_Entity.class.getMethod(getterName);
						Object value = getter.invoke(modRecord);

						if (value == null) {
							continue;
						}

						if (setSql.length() > 0) {
							setSql.append(", ");
						}
						setSql.append(columnName).append(" = ?");
						args.add(value);

					} catch (NoSuchMethodException e) {
						// Skip
					} catch (Exception e) {
						throw new RuntimeException("Error transferring column to live tables: " + columnName, e);
					}
				}
			}
		}

		if (args.isEmpty()) {
			return;
		}

		args.add(reportDate);
		Object[] argArray = args.toArray();

		jdbcTemplate.update("UPDATE BRRS_MASTER_SUMMARYTABLE SET " + setSql + " WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
				argArray);
		jdbcTemplate.update("UPDATE BRRS_MASTER_DETAILTABLE SET " + setSql + " WHERE TRUNC(REPORT_DATE) = TRUNC(?)",
				argArray);
	}

